import { useState } from "react";

import type { CaseView, PlannerName, TraceSummary } from "../api/types";
import { count, plannerName } from "../format";

const PLANNERS: PlannerName[] = ["meta", "info_gain", "sweep", "random"];
/** Fresh machines are generated by the simulator from this seed alone (D-74). */
export const MAX_MACHINE_SEED = 10000;
/** Replays shown before "Show all"; the full list grows with every live run. */
const REPLAY_PAGE_SIZE = 8;

interface Props {
  cases: CaseView[];
  replays: TraceSummary[];
  metaConfigured: boolean;
  busy: boolean;
  onRun: (caseView: CaseView, planner: PlannerName, seed: number) => void;
  /** Investigate a machine nobody has seen: generated from `machineSeed`, not a sealed case. */
  onRunFresh: (machineSeed: number, planner: PlannerName, seed: number) => void;
  onOpenReplay: (id: string) => void;
}

export default function CasePicker({
  cases,
  replays,
  metaConfigured,
  busy,
  onRun,
  onRunFresh,
  onOpenReplay,
}: Props) {
  const [planner, setPlanner] = useState<PlannerName>(metaConfigured ? "meta" : "info_gain");
  const [seed, setSeed] = useState(0);
  // A random starting seed: a fixed default would already have a saved replay,
  // so the "unseen" machine would not be unseen.
  const [machineSeed, setMachineSeed] = useState(() =>
    Math.floor(Math.random() * (MAX_MACHINE_SEED + 1)),
  );
  const metaUnavailable = planner === "meta" && !metaConfigured;
  const seedSeen = replays.some((r) => r.investigation_id.startsWith(`fresh-${machineSeed}-`));
  const [replayQuery, setReplayQuery] = useState("");
  const [showAllReplays, setShowAllReplays] = useState(false);
  const filteredReplays = replays.filter((r) =>
    `${r.investigation_id} ${r.case_id} ${plannerName(r.planner)}`
      .toLowerCase()
      .includes(replayQuery.trim().toLowerCase()),
  );
  const visibleReplays = showAllReplays
    ? filteredReplays
    : filteredReplays.slice(0, REPLAY_PAGE_SIZE);

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-end gap-4 text-sm">
        <label className="flex flex-col gap-1">
          Investigator
          <select
            className="rounded border border-slate-300 bg-white px-2 py-1 dark:border-slate-700 dark:bg-slate-900"
            value={planner}
            onChange={(e) => setPlanner(e.target.value as PlannerName)}
          >
            {PLANNERS.map((p) => (
              <option key={p} value={p}>
                {plannerName(p)}
                {p === "meta" && !metaConfigured ? " (not configured)" : ""}
              </option>
            ))}
          </select>
        </label>
        <label className="flex flex-col gap-1">
          Seed
          <input
            type="number"
            min={0}
            max={10000}
            className="w-24 rounded border border-slate-300 bg-white px-2 py-1 dark:border-slate-700 dark:bg-slate-900"
            value={seed}
            onChange={(e) => setSeed(Math.trunc(Math.max(0, Math.min(10000, Number(e.target.value) || 0))))}
          />
        </label>
        {metaUnavailable && (
          <p role="note" className="text-amber-700 dark:text-amber-400">
            The Meta model is not configured on the backend; choose another investigator.
          </p>
        )}
      </div>

      <section aria-labelledby="cases-heading">
        <h3 id="cases-heading" className="mb-1 font-semibold">
          Sealed cases
        </h3>
        <p className="mb-2 text-sm text-slate-600 dark:text-slate-400">
          Six machines with hidden faults and a human maintenance note each.
        </p>
        <ul
          className="divide-y divide-slate-200 border-y border-slate-200 dark:divide-slate-800 dark:border-slate-800"
          aria-label="Cases"
        >
          {cases.map((c) => (
            <li
              key={c.case_id}
              className="flex flex-wrap items-center justify-between gap-x-6 gap-y-2 py-3"
            >
              <div className="min-w-64 flex-1">
                <h4 className="font-semibold">
                  {c.title}{" "}
                  <span className="ml-1 font-mono text-xs font-normal text-slate-500">
                    {c.case_id}
                  </span>
                </h4>
                <p className="mt-0.5 text-sm italic text-slate-600 dark:text-slate-400">
                  “{c.note}”
                </p>
              </div>
              <button
                type="button"
                disabled={busy || metaUnavailable}
                onClick={() => onRun(c, planner, seed)}
                className="rounded-sm bg-slate-900 px-3 py-1.5 text-sm font-medium text-white hover:bg-slate-700 disabled:opacity-40 focus:outline-none focus-visible:ring-2 focus-visible:ring-slate-500 dark:bg-slate-100 dark:text-slate-900 dark:hover:bg-white"
              >
                Investigate {c.title}
              </button>
            </li>
          ))}
        </ul>
      </section>

      <section className="rounded-sm border border-dashed border-slate-400 p-4 dark:border-slate-600">
        <div className="flex flex-wrap items-center justify-between gap-x-6 gap-y-3">
          <div className="min-w-64 flex-1">
            <h3 className="font-semibold">
              Unseen machine{" "}
              <span className="ml-1 font-mono text-xs font-normal text-slate-500">
                fresh-{machineSeed}
              </span>
            </h3>
            <p className="mt-0.5 text-sm text-slate-600 dark:text-slate-400">
              A new simulated machine generated from the seed alone, with no maintenance history:
              the investigator must find its fault from measurements.
            </p>
            {seedSeen && (
              <p role="note" className="mt-1 text-sm text-amber-700 dark:text-amber-400">
                Seed {machineSeed} already has a saved investigation, so it is no longer unseen —
                pick another seed for a machine nobody has run.
              </p>
            )}
          </div>
          <div className="flex flex-wrap items-end gap-3 text-sm">
            <label className="flex flex-col gap-1">
              Machine seed
              <input
                type="number"
                min={0}
                max={MAX_MACHINE_SEED}
                className="w-24 rounded-sm border border-slate-300 bg-white px-2 py-1 dark:border-slate-700 dark:bg-slate-900"
                value={machineSeed}
                onChange={(e) =>
                  setMachineSeed(
                    Math.trunc(Math.max(0, Math.min(MAX_MACHINE_SEED, Number(e.target.value) || 0))),
                  )
                }
              />
            </label>
            <button
              type="button"
              disabled={busy || metaUnavailable}
              onClick={() => onRunFresh(machineSeed, planner, seed)}
              className="rounded-sm bg-slate-900 px-3 py-1.5 font-medium text-white hover:bg-slate-700 disabled:opacity-40 focus:outline-none focus-visible:ring-2 focus-visible:ring-slate-500 dark:bg-slate-100 dark:text-slate-900 dark:hover:bg-white"
            >
              Investigate unseen machine
            </button>
          </div>
        </div>
      </section>

      <section aria-labelledby="replays-heading">
        <h3 id="replays-heading" className="mb-2 font-semibold">
          Saved replays
        </h3>
        {replays.length === 0 ? (
          <p className="text-sm text-slate-500">No saved investigations yet.</p>
        ) : (
          <>
            <label className="mb-2 flex max-w-md flex-col gap-1 text-sm">
              Filter saved replays
              <input
                type="search"
                value={replayQuery}
                onChange={(e) => setReplayQuery(e.target.value)}
                placeholder="e.g. case-r2, meta, fresh-77"
                className="rounded border border-slate-300 bg-white px-2 py-1 dark:border-slate-700 dark:bg-slate-900"
              />
            </label>
            <p className="mb-1 text-xs text-slate-500">
              Showing {visibleReplays.length} of {filteredReplays.length} replays
              {filteredReplays.length !== replays.length && ` (${replays.length} saved)`}
            </p>
            {visibleReplays.length === 0 ? (
              <p className="text-sm text-slate-500">No saved replay matches that filter.</p>
            ) : (
              <ul className="divide-y divide-slate-200 text-sm dark:divide-slate-800">
                {visibleReplays.map((r) => (
              <li key={r.investigation_id} className="flex items-center justify-between gap-3 py-1.5">
                <span>
                  {r.demo && (
                    <span className="mr-2 rounded bg-slate-200 px-1.5 text-xs text-slate-700 dark:bg-slate-700 dark:text-slate-200">
                      demo
                    </span>
                  )}
                  {/* No diagnosis here: it would reveal the hidden fault next to the case cards. */}
                  <span className="font-mono">{r.investigation_id}</span> · {plannerName(r.planner)}{" "}
                  · seed {r.seed} · {count(r.experiments, "experiment")} · {count(r.cost, "point")}
                </span>
                <button
                  type="button"
                  disabled={busy}
                  className="rounded border border-slate-300 px-2 py-0.5 hover:bg-slate-100 dark:border-slate-700 dark:hover:bg-slate-800"
                  onClick={() => onOpenReplay(r.investigation_id)}
                  aria-label={`Open replay ${r.investigation_id}`}
                >
                  Open
                </button>
                </li>
                ))}
              </ul>
            )}
            {filteredReplays.length > REPLAY_PAGE_SIZE && (
              <button
                type="button"
                onClick={() => setShowAllReplays((v) => !v)}
                className="mt-2 text-sm text-blue-700 underline dark:text-blue-400"
              >
                {showAllReplays
                  ? "Show fewer replays"
                  : `Show all ${filteredReplays.length} replays`}
              </button>
            )}
          </>
        )}
      </section>
    </div>
  );
}
